import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;

import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ValueResolutionScopeActivationTest {
	@Test
	void nestedForegroundAndWorkerRestoreExactClosedExposure(@TempDir File directory) throws Exception {
		ValueStore store = new ValueStore(directory, new LmdbStoreConfig());
		try (var outer = store.openValueResolutionScope(); var inner = store.openValueResolutionScope()) {
			assertNull(ValueResolutionScope.activeExposure(store));
			try (var first = outer.activateForeground()) {
				assertSame(outer, ValueResolutionScope.current(store));
				try (var same = outer.activateForeground(); var worker = outer.activate()) {
					assertSame(outer, ValueResolutionScope.current(store));
				}
				try (var second = inner.activateForeground()) {
					assertSame(inner, ValueResolutionScope.current(store));
					outer.close();
					inner.retireReaders();
					assertSame(inner, ValueResolutionScope.current(store));
					inner.close();
					assertNull(ValueResolutionScope.current(store));
					assertSame(inner, ValueResolutionScope.activeExposure(store));
				}
				assertNull(ValueResolutionScope.current(store));
				assertSame(outer, ValueResolutionScope.activeExposure(store));
				assertTrue(ValueResolutionScope.hasActiveExposure(store));
			}
			assertNull(ValueResolutionScope.activeExposure(store));
		} finally {
			store.close();
		}
	}

	@Test
	void foreignStoreAndExceptionalCallbackRestoreCaller(@TempDir File directory) throws Exception {
		ValueStore first = new ValueStore(new File(directory, "first"), new LmdbStoreConfig());
		ValueStore second = new ValueStore(new File(directory, "second"), new LmdbStoreConfig());
		try (var a = first.openValueResolutionScope();
				var b = second.openValueResolutionScope();
				var outer = a.activateForeground()) {
			try {
				try (var inner = b.activateForeground()) {
					assertNull(ValueResolutionScope.activeExposure(first));
					assertSame(b, ValueResolutionScope.current(second));
					throw new IllegalStateException("callback");
				}
			} catch (IllegalStateException expected) {
				assertEquals("callback", expected.getMessage());
				assertSame(a, ValueResolutionScope.current(first));
				assertNull(ValueResolutionScope.activeExposure(second));
			}
		} finally {
			first.close();
			second.close();
		}
		assertNull(ValueResolutionScope.activeExposure(first));
	}
}
